import os
from cerebras.cloud.sdk import Cerebras

client = Cerebras(
    api_key=os.environ.get("CEREBRAS_API_KEY")
)

def scan_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()
    except Exception as e:
        return f"Could not read {file_path}: {e}\n"

    prompt = f"""ROLE AND OBJECTIVE

You are an uncompromising, world-class Senior Security Researcher and Static Code Analysis Engine. Your goal is to perform a Deep Code Inspection of the provided snippet. You possess zero tolerance for inefficiency, insecurity, or logical flaws.

CRITICAL INSTRUCTIONS

You must analyze the code not just superficially, but by simulating its execution state-by-state. You are looking for:

1. Logical Errors: Infinite loops, off-by-one errors, race conditions, deadlocks.

2. Security Vulnerabilities: Injection flaws, broken authentication, sensitive data exposure, XSS, CSRF.

3. Performance Bottlenecks: Inefficient algorithms, memory leaks, unnecessary computations.

Analyze the following file: {file_path}

Content:

{content}
"""

    response_text = f"--- SCAN RESULTS FOR: {file_path} ---\n"

    try:
        stream = client.chat.completions.create(
            messages=[
                {
                    "role": "system",
                    "content": prompt
                }
            ],
            model="llama3.1-70b",
            stream=True,
            max_completion_tokens=65000,
            temperature=1,
            top_p=0.95
        )

        for chunk in stream:
            if chunk.choices[0].delta.content:
                response_text += chunk.choices[0].delta.content

        response_text += "\n\n"
    except Exception as e:
        response_text += f"Error analyzing {file_path}: {e}\n\n"

    return response_text

def main():
    exclude_dirs = {'.git', '.replit', '__pycache__', 'node_modules', 'venv', '.pythonlibs'}
    exclude_files = {'hibak.txt', 'scan_project.py', 'package-lock.json', 'uv.lock', 'pyproject.toml'}

    all_results = ""

    for root, dirs, files in os.walk('.'):
        dirs[:] = [d for d in dirs if d not in exclude_dirs]

        for file in files:
            if file in exclude_files:
                continue

            file_path = os.path.join(root, file)
            print(f"Scanning {file_path}...")
            all_results += scan_file(file_path)

    with open('hibak.txt', 'w', encoding='utf-8') as f:
        f.write(all_results)

    print("Scan complete. Results saved in hibak.txt")

if __name__ == "__main__":
    main()
```
